// 1. Validar código de estado
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Validar que el body tenga la propiedad token
pm.test("Body has token property", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("token");
    pm.expect(jsonData.token).to.be.a("string").and.not.empty;
});

// 3. Validar los headers
pm.test("Content-Type is JSON", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

// 4. Guardar el token en una variable de entorno
var jsonData = pm.response.json();
var tokenLimpio = jsonData.token.trim();
pm.environment.set("token", tokenLimpio);
console.log("Token guardado: " + tokenLimpio);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response has data array", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("data").that.is.an("array");
    pm.expect(jsonData.data.length).to.be.greaterThan(0);
});

pm.test("First user has email", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.data[0]).to.have.property("email");
});

pm.test("Response time < 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Status 201 Created", function () {
    pm.response.to.have.status(201);
});

pm.test("Response has id and createdAt", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("id");
    pm.expect(jsonData).to.have.property("createdAt");
    pm.expect(jsonData.name).to.eql("Ana");
});

pm.test("Job matches", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.job).to.eql("QA Engineer");
});

pm.test("Status 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Job was updated", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.job).to.eql("Senior QA");
});

pm.test("Response has updatedAt", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("updatedAt");
});

pm.test("Status 204 No Content", function () {
    pm.response.to.have.status(204);
});

pm.test("Body is empty", function () {
    pm.expect(pm.response.text()).to.be.empty;
});
